1	import { randomUUID } from 'node:crypto';
2	import request from 'supertest';
3	import { afterAll, beforeAll, expect, test, vi } from 'vitest';
4	import type { MentorDto } from '../shared/types.ts';
5	import { createApp, createClock } from './app.ts';
6	import { createSmtpMailer, type EmailMessage, type Mailer } from './email.ts';
7	import { createTestDb, insertMentor, type TestDb } from './test-db.ts';
8	
9	let db: TestDb;
10	let pool: TestDb['pool'];
11	const sent: EmailMessage[] = [];
12	const mailer: Mailer = { send: async (message) => void sent.push(message) };
13	const NOW = new Date('2026-10-20T12:00:00Z');
14	const clock = { now: () => NOW, demo: false };
15	// weekdays 1-5, 20:30-23:30 in Asia/Kolkata: classes at 15:00, 16:00 and 17:00 UTC
16	const ukHours = [1, 2, 3, 4, 5].map((weekday) => ({ weekday, start: '20:30', end: '23:30' }));
17	const valid = { startsAt: '2026-10-27T16:00:00Z', parentName: 'Asha Patel', parentEmail: 'asha@example.com', childName: 'Rohan', parentTimeZone: 'Europe/London' };
18	let app: ReturnType<typeof createApp>;
19	
20	beforeAll(async () => {
21	  db = await createTestDb();
22	  pool = db.pool;
23	  await insertMentor(pool, { timeZone: 'Asia/Kolkata', hours: ukHours });
24	  await insertMentor(pool, { timeZone: 'Asia/Kolkata', hours: ukHours });
25	  app = createApp({ pool, clock, mailer, appUrl: 'http://localhost:3000' });
26	});
27	afterAll(() => db.drop());
28	
29	test('books a class, then emails both sides', async () => {
30	  const res = await request(app).post('/api/bookings').send(valid);
31	  expect(res.status).toBe(201);
32	  expect(res.body.booking).toMatchObject({ startsAt: '2026-10-27T16:00:00.000Z', endsAt: '2026-10-27T17:00:00.000Z',
33	    childName: 'Rohan', parentTimeZone: 'Europe/London', mentor: { timeZone: 'Asia/Kolkata' } });
34	  await vi.waitFor(() => expect(sent.map((m) => m.to)).toContain('asha@example.com'));
35	  expect(sent).toHaveLength(2);
36	});
37	
38	test('accepts another offset for the same instant', async () => {
39	  const res = await request(app).post('/api/bookings').send({ ...valid, startsAt: '2026-10-27T18:00:00+01:00' });
40	  expect([res.status, res.body.booking.startsAt]).toEqual([201, '2026-10-27T17:00:00.000Z']);
41	});
42	
43	test('rejects bad input with field errors', async () => {
44	  const res = await request(app).post('/api/bookings')
45	    .send({ ...valid, parentName: '   ', childName: 'Ro\nhan', parentEmail: 'nope', parentTimeZone: 'IST', startsAt: '2026-10-27T16:30:00Z' });
46	  expect(res.status).toBe(400);
47	  expect(res.body.error.code).toBe('VALIDATION_FAILED');
48	  expect(Object.keys(res.body.error.fields).sort()).toEqual(['childName', 'parentEmail', 'parentName', 'parentTimeZone', 'startsAt']);
49	});
50	
51	test('rejects a body that is not JSON', async () => {
52	  const res = await request(app).post('/api/bookings').set('content-type', 'application/json').send('{oops');
53	  expect([res.status, res.body.error.code]).toEqual([400, 'VALIDATION_FAILED']);
54	});
55	
56	test('a body over the JSON limit is a 400, not a server error', async () => {
57	  const log = vi.fn();
58	  const quiet = createApp({ pool, clock, mailer, appUrl: '', log });
59	  const res = await request(quiet).post('/api/bookings').send({ ...valid, parentName: 'x'.repeat(200_000) });
60	  expect([res.status, res.body.error.code]).toEqual([400, 'VALIDATION_FAILED']);
61	  expect(log).not.toHaveBeenCalled();
62	});
63	
64	test('names with line or paragraph separators are rejected', async () => {
65	  const res = await request(app).post('/api/bookings').send({ ...valid, parentName: 'As\u2029ha', childName: 'Ro\u2028han' });
66	  expect(res.status).toBe(400);
67	  expect(Object.keys(res.body.error.fields).sort()).toEqual(['childName', 'parentName']);
68	});
69	
70	test('409 when nobody is left for that hour, or it is too soon', async () => {
71	  const at = { ...valid, startsAt: '2026-10-28T15:00:00Z' };
72	  await request(app).post('/api/bookings').send(at);
73	  await request(app).post('/api/bookings').send(at);
74	  for (const body of [at, { ...valid, startsAt: '2026-10-20T13:00:00Z' }]) {
75	    const res = await request(app).post('/api/bookings').send(body);
76	    expect([res.status, res.body.error.code]).toEqual([409, 'SLOT_UNAVAILABLE']);
77	  }
78	});
79	
80	test('fetches a booking by id, and 404s otherwise', async () => {
81	  const made = await request(app).post('/api/bookings').send({ ...valid, startsAt: '2026-10-29T15:00:00Z' });
82	  const res = await request(app).get(`/api/bookings/${made.body.booking.id}`);
83	  expect(res.body.booking.id).toBe(made.body.booking.id);
84	  for (const id of [randomUUID(), 'abc']) expect((await request(app).get(`/api/bookings/${id}`)).body.error.code).toBe('NOT_FOUND');
85	});
86	
87	test('lists slots from the app clock, full hours included', async () => {
88	  const res = await request(app).get('/api/slots');
89	  expect([res.body.now, res.body.demo]).toEqual(['2026-10-20T12:00:00.000Z', false]);
90	  expect(res.body.slots[0].startsAt).toBe('2026-10-20T15:00:00.000Z');
91	  expect(res.body.slots).toContainEqual({ startsAt: '2026-10-28T15:00:00.000Z', available: false });
92	});
93	
94	test('lists mentors with upcoming booking times only', async () => {
95	  const res = await request(app).get('/api/mentors');
96	  expect(res.body.mentors).toHaveLength(2);
97	  const times = res.body.mentors.flatMap((m: MentorDto) => m.bookings);
98	  expect(times.length).toBeGreaterThan(0);
99	  expect(times.every((b: object) => Object.keys(b).join() === 'startsAt')).toBe(true);
100	});
101	
102	test('every /api response is no-store, and unknown routes are JSON 404s', async () => {
103	  expect((await request(app).get('/api/slots')).headers['cache-control']).toBe('no-store');
104	  const res = await request(app).get('/api/nope');
105	  expect([res.status, res.headers['cache-control'], res.body.error.code]).toEqual([404, 'no-store', 'NOT_FOUND']);
106	});
107	
108	test('the booking is answered before any email settles', async () => {
109	  const stuck = createApp({ pool, clock, appUrl: '', mailer: { send: () => new Promise<void>(() => {}) } }); // never settles
110	  const res = await request(stuck).post('/api/bookings').send({ ...valid, startsAt: '2026-11-02T15:00:00Z' });
111	  expect(res.status).toBe(201);
112	});
113	
114	test('a failing mailer never fails the booking', async () => {
115	  const log = vi.fn();
116	  const broken = createApp({ pool, clock, appUrl: '', log, mailer: createSmtpMailer('smtp://127.0.0.1:9') }); // nothing listens on port 9
117	  const res = await request(broken).post('/api/bookings').send({ ...valid, startsAt: '2026-10-30T15:00:00Z' });
118	  expect(res.status).toBe(201);
119	  await vi.waitFor(() => expect(log).toHaveBeenCalled());
120	});
121	
122	test('the app clock drives slots, booking and the mentors list', async () => {
123	  // a clock before any real run, so a route that reads new Date() fails here
124	  const demo = createApp({ pool, clock: { now: () => new Date('2026-10-14T13:30:00Z'), demo: true }, mailer, appUrl: '' });
125	  const slots = (await request(demo).get('/api/slots')).body;
126	  expect([slots.now, slots.demo, slots.slots[0].startsAt])
127	    .toEqual(['2026-10-14T13:30:00.000Z', true, '2026-10-14T16:00:00.000Z']); // 15:00Z is under 2 hours away
128	  expect((await request(demo).post('/api/bookings').send({ ...valid, startsAt: '2026-10-15T15:00:00Z' })).status).toBe(201);
129	  const mentors = (await request(demo).get('/api/mentors')).body;
130	  expect(mentors.demo).toBe(true);
131	  expect(mentors.now).toBe('2026-10-14T13:30:00.000Z');
132	  expect(mentors.mentors.flatMap((m: MentorDto) => m.bookings.map((b) => b.startsAt))).toContain('2026-10-15T15:00:00.000Z');
133	});
134	
135	test('createClock: real by default, demo clock starts at DEMO_NOW and keeps ticking', () => {
136	  let real = 1_000_000;
137	  expect(createClock(undefined, () => real)).toMatchObject({ demo: false });
138	  expect(createClock('', () => real).now().getTime()).toBe(1_000_000);
139	  const c = createClock('2026-10-20T12:00:00Z', () => real);
140	  expect([c.demo, c.now().toISOString()]).toEqual([true, '2026-10-20T12:00:00.000Z']);
141	  real += 90_000;
142	  expect(c.now().toISOString()).toBe('2026-10-20T12:01:30.000Z');
143	  expect(() => createClock('next tuesday')).toThrow(/DEMO_NOW/);
144	  expect(() => createClock('2026-10-20T12:00:00')).toThrow(/DEMO_NOW/); // no offset would read in the host zone
145	});
