 20 │   if (!z.iso.datetime({ offset: true }).safeParse(demoNow).success) throw new Error('DEMO_NOW must be an ISO instant');
 21 │   const offset = Date.parse(demoNow) - realNow();
 22 │   return { now: () => new Date(realNow() + offset), demo: true };
 23 │ }
